// Step: Generate Alert (CAP Protocol)
const payload = $input.first().json.body || $input.first().json;
const incident = payload.incident || {};
const zone = incident.primaryLocation?.name || 'Zone A';

const alertPayload = {
  alertId: `CAP-${incident.code || 'ALERT'}-${Date.now().toString(36).toUpperCase()}`,
  headline: `URGENT FLOOD EVACUATION: ${zone}`,
  severity: 'Extreme',
  urgency: 'Immediate',
  certainty: 'Observed',
  instruction: `Water level surge detected at ${incident.metrics?.waterLevelMeters || 3.2}m. Evacuate via Route R4 highland arterial. Avoid low-lying river bridges.`,
  targetPolygons: [zone],
  generatedAt: new Date().toISOString()
};

return [{
  json: {
    ...payload,
    alertPayload
  }
}];

// Step: Log Alert to Audit Ledger
const data = $input.first().json;

const auditLog = {
  auditId: `AUDIT-ALT-${Date.now()}`,
  alertId: data.alertPayload?.alertId,
  status: 'SIMULATION_BROADCAST_CONFIRMED',
  loggedAt: new Date().toISOString(),
  disclaimer: 'Prototype simulation: no real EAS broadcast.'
};

return [{
  json: {
    ...data,
    auditLog,
    emergencyAlert: 'SIMULATED'
  }
}];
